import { createServer } from "node:http";
import { readFileSync, existsSync } from "node:fs";
import { extname, join } from "node:path";
import { createRequire } from "node:module";

const require = createRequire("/Users/sinchunyeung/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/package.json");
const { chromium } = require("playwright");

const WEB = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".png": "image/png",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json",
};

function makeStep(streamIdx, pi, p0) {
  return {
    stream_idx: streamIdx,
    pi,
    Gi: [
      [pi[0] - 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] + 0.4],
      [pi[0] - 0.4, pi[1] + 0.4],
    ],
    buffer: [p0, pi],
    candidates: [{ grid_pt_idx: 0, alive: true, F: [], S: [] }],
  };
}

const p0 = [0, 0];
const p1 = [2, 1];
const p2 = [4, 0];
const header = {
  type: "header",
  eps: 0.9,
  delta: 500,
  grid_val: 12.5,
  r_val: 8.2,
  expected_frechet: 1.25,
  bbox: [-1, -1, 6, 3],
  stream: [p0, p1, p2],
};
const prefix = {
  type: "prefix",
  data: {
    start_idx: 0,
    end_idx: 2,
    p0_idx: 0,
    p0,
    P: [[0.2, 0.2], [0.3, -0.1]],
    output: [p0, p2],
    steps: [makeStep(1, p1, p0), makeStep(2, p2, p0)],
  },
};
const done = {
  type: "done",
  time_ms: 12.4,
  simplified: [p0, p2],
  frechet_distance: 0.41,
};
const ndjson = [header, prefix, done].map((o) => JSON.stringify(o)).join("\n") + "\n";

let delayMs = 0;

const server = createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, label: "Demo", n_points: 3 }] }));
    return;
  }
  if (url.pathname === "/api/trace/1" || url.pathname === "/api/trace") {
    const body = ndjson;
    const send = () => {
      res.writeHead(200, { "Content-Type": "application/x-ndjson" });
      res.end(body);
    };
    if (delayMs > 0) setTimeout(send, delayMs);
    else send();
    return;
  }
  if (url.pathname === "/api/frechet") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ distance: 0.4123 }));
    return;
  }
  const filePath = join(WEB, url.pathname === "/" ? "index.html" : url.pathname);
  if (!filePath.startsWith(WEB) || !existsSync(filePath)) {
    res.writeHead(404);
    res.end("not found");
    return;
  }
  res.writeHead(200, { "Content-Type": MIME[extname(filePath)] || "text/plain" });
  res.end(readFileSync(filePath));
});

async function snapshot(page, extra = {}) {
  return page.evaluate((extra) => {
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const box = (el) => {
      if (!el) return null;
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return {
        x: Math.round(r.x),
        y: Math.round(r.y),
        w: Math.round(r.width),
        h: Math.round(r.height),
        right: Math.round(r.x + r.width),
        bottom: Math.round(r.y + r.height),
        display: cs.display,
        visibility: cs.visibility,
        text: (el.innerText || "").replace(/\s+/g, " ").trim().slice(0, 180),
        html: el.innerHTML.slice(0, 240),
      };
    };
    const overflows = [];
    document.querySelectorAll("body *").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      if (el.id === "tracePicker" || el.closest("#tracePicker")) return;
      const r = el.getBoundingClientRect();
      if (r.width < 2 && r.height < 2) return;
      if (getComputedStyle(el).position === "fixed") return;
      if (r.x + r.width > vw + 2) {
        overflows.push({
          id: el.id,
          cls: String(el.className).slice(0, 60),
          tag: el.tagName,
          right: Math.round(r.x + r.width),
          x: Math.round(r.x),
          w: Math.round(r.width),
          text: (el.innerText || "").replace(/\s+/g, " ").trim().slice(0, 70),
        });
      }
    });
    const pb = document.getElementById("playbackBar");
    const pbControls = pb
      ? [...pb.querySelectorAll("button, input, .speed-preset")].map((el) => {
          const r = el.getBoundingClientRect();
          const clipped =
            r.width < 8 ||
            r.height < 8 ||
            r.x + r.width < 0 ||
            r.y + r.height < 0 ||
            r.x > vw ||
            r.bottom > vh + 2;
          return {
            id: el.id,
            text: (el.innerText || el.value || el.title || "").replace(/\s+/g, " ").trim().slice(0, 40),
            x: Math.round(r.x),
            y: Math.round(r.y),
            w: Math.round(r.width),
            h: Math.round(r.height),
            clipped,
            disabled: el.disabled,
          };
        })
      : [];
    const header = document.querySelector("header");
    const params = document.getElementById("paramsBar");
    const loadBtn = document.getElementById("loadBtn");
    const hud = document.getElementById("traceLoadingHud");
    const drop = document.getElementById("dropHint");
    const dock = document.getElementById("mobileTransport");
    const sidebar = document.getElementById("sidebar");
    const status = document.getElementById("statusGrid");
    const canvas = document.getElementById("canvasContainer");
    const paramsChildren = params
      ? [...params.children].map((c) => {
          const r = c.getBoundingClientRect();
          return {
            text: (c.innerText || "").replace(/\s+/g, " ").trim().slice(0, 80),
            x: Math.round(r.x),
            y: Math.round(r.y),
            w: Math.round(r.width),
            h: Math.round(r.height),
            right: Math.round(r.x + r.width),
          };
        })
      : [];
    return {
      vw,
      vh,
      bodyClass: document.body.className,
      scrollW: document.documentElement.scrollWidth,
      scrollH: document.documentElement.scrollHeight,
      pageOverflowX: document.documentElement.scrollWidth > vw + 1,
      header: box(header),
      params: box(params),
      paramsChildren,
      loadBtn: box(loadBtn),
      uploadStatus: box(document.getElementById("uploadStatus")),
      hud: box(hud),
      hudVisible: hud ? hud.classList.contains("visible") : false,
      drop: box(drop),
      dropDisplay: drop ? getComputedStyle(drop).display : null,
      playback: box(pb),
      pbControls,
      dock: box(dock),
      dockDisplay: dock ? getComputedStyle(dock).display : null,
      sidebar: box(sidebar),
      sidebarDisplay: sidebar ? getComputedStyle(sidebar).display : null,
      status: box(status),
      canvas: box(canvas),
      overflows: overflows.slice(0, 12),
      hasFrechet: (params?.innerText || "").includes("Fréchet") || (params?.innerText || "").includes("Frechet"),
      hasTime: (params?.innerText || "").includes("Simplification time"),
      hasSpinner: !!params?.querySelector(".params-spinner"),
      extra,
    };
  }, extra);
}

async function waitForOption(page) {
  await page.waitForFunction(() => {
    const sel = document.getElementById("traceSelect");
    return sel && [...sel.options].some((o) => o.value === "1");
  }, { timeout: 8000 });
}

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = server.address().port;
const browser = await chromium.launch({ channel: "chrome" });
const out = {};

async function withPage(size, fn) {
  const page = await browser.newPage();
  await page.setViewportSize(size);
  await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
  try {
    return await fn(page);
  } finally {
    await page.close();
  }
}

try {
  delayMs = 0;
  out.start1280 = await withPage({ width: 1280, height: 800 }, async (page) => {
    await waitForOption(page);
    return snapshot(page);
  });
  out.start900 = await withPage({ width: 900, height: 700 }, async (page) => {
    await waitForOption(page);
    return snapshot(page);
  });
  out.start390 = await withPage({ width: 390, height: 844 }, async (page) => {
    await waitForOption(page);
    return snapshot(page);
  });

  delayMs = 1500;
  out.loading1280 = await withPage({ width: 1280, height: 800 }, async (page) => {
    await waitForOption(page);
    await page.selectOption("#traceSelect", "1");
    await page.click("#loadBtn");
    await page.waitForFunction(() => document.body.classList.contains("trace-loading"), { timeout: 4000 });
    await page.waitForTimeout(200);
    return snapshot(page);
  });
  out.loading390 = await withPage({ width: 390, height: 844 }, async (page) => {
    await waitForOption(page);
    await page.click("#preloadedTrigger");
    await page.waitForTimeout(200);
    await page.click(".trace-picker-item");
    await page.click("#loadBtn");
    await page.waitForFunction(() => document.body.classList.contains("trace-loading"), { timeout: 4000 });
    await page.waitForTimeout(200);
    return snapshot(page);
  });

  delayMs = 0;
  async function loadedSnap(size) {
    return withPage(size, async (page) => {
      await waitForOption(page);
      if (size.width <= 720) {
        await page.click("#preloadedTrigger");
        await page.waitForTimeout(150);
        await page.click(".trace-picker-item");
      } else {
        await page.selectOption("#traceSelect", "1");
      }
      await page.click("#loadBtn");
      await page.waitForFunction(() => document.body.classList.contains("playback-ready"), { timeout: 8000 });
      await page.waitForTimeout(500);
      try { await page.evaluate(() => window.MathJax?.typesetPromise?.()); } catch {}
      await page.waitForTimeout(300);
      return snapshot(page);
    });
  }
  out.loaded1280 = await loadedSnap({ width: 1280, height: 800 });
  out.loaded1024 = await loadedSnap({ width: 1024, height: 768 });
  out.loaded900 = await loadedSnap({ width: 900, height: 700 });
  out.loaded390 = await loadedSnap({ width: 390, height: 844 });

  const slim = (s) => ({
    vw: s.vw,
    bodyClass: s.bodyClass,
    headerH: s.header?.h,
    headerText: s.header?.text,
    paramsText: s.params?.text,
    paramsH: s.params?.h,
    paramsW: s.params?.w,
    paramsChildren: s.paramsChildren,
    hasFrechet: s.hasFrechet,
    hasTime: s.hasTime,
    hasSpinner: s.hasSpinner,
    loadBtn: s.loadBtn && { w: s.loadBtn.w, h: s.loadBtn.h, text: s.loadBtn.text },
    uploadStatus: s.uploadStatus && { text: s.uploadStatus.text, w: s.uploadStatus.w },
    hudVisible: s.hudVisible,
    hud: s.hud && { display: s.hud.display, text: s.hud.text },
    dropDisplay: s.dropDisplay,
    playbackH: s.playback?.h,
    pbClipped: (s.pbControls || []).filter((c) => c.clipped),
    pbControls: s.pbControls,
    dockDisplay: s.dockDisplay,
    sidebarDisplay: s.sidebarDisplay,
    canvas: s.canvas && { h: s.canvas.h, w: s.canvas.w },
    pageOverflowX: s.pageOverflowX,
    scrollW: s.scrollW,
    overflows: s.overflows,
  });

  const result = {};
  for (const [k, v] of Object.entries(out)) result[k] = slim(v);
  console.log(JSON.stringify(result, null, 2));
} finally {
  await browser.close();
  server.close();
}

