const header = {
  type: "header",
  eps: 0.9,
  delta: 500,
  grid_val: 12.5,
  r_val: 8.2,
  expected_frechet: 1.25,
  bbox: [-1, -1, 6, 3],
  stream: [p0, p1, p2],
};
const prefix = {
  type: "prefix",
  data: {
    start_idx: 0,
    end_idx: 2,
    p0_idx: 0,
    p0,
    P: [[0.2, 0.2], [0.3, -0.1]],
    output: [p0, p2],
    steps: [makeStep(1, p1, p0), makeStep(2, p2, p0)],
  },
};
const done = {
  type: "done",
  time_ms: 12.4,
  simplified: [p0, p2],
  frechet_distance: 0.41,
};
const ndjson = [header, prefix, done].map((o) => JSON.stringify(o)).join("\n") + "\n";

const server = createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
