  }
  if (url.pathname === "/api/trace/1" || url.pathname === "/api/trace") {
    setTimeout(() => {
      res.writeHead(200, { "Content-Type": "application/x-ndjson" });
      res.end(ndjson);
    }, 2000);
    return;
  }
  if (url.pathname === "/api/frechet") {
