async function waitForOption(page) {
  await page.waitForFunction(() => {
    const sel = document.getElementById("traceSelect");
    return sel && [...sel.options].some((o) => o.value === "1");
  }, { timeout: 8000 });
}

async function measureLoading(page) {
  return page.evaluate(() => {
    const params = document.getElementById("paramsBar");
    const header = document.querySelector("header");
    const kids = params
      ? [...params.children].map((c) => {
          const r = c.getBoundingClientRect();
          return {
            text: (c.innerText || "").replace(/\s+/g, " ").trim(),
            x: Math.round(r.x),
            y: Math.round(r.y),
            w: Math.round(r.width),
            right: Math.round(r.x + r.width),
          };
        })
      : [];
    return {
      vw: window.innerWidth,
      headerH: header ? Math.round(header.getBoundingClientRect().height) : null,
      paramsText: (params?.innerText || "").replace(/\s+/g, " ").trim(),
      hasFrechet: (params?.innerText || "").includes("Fréchet"),
      hasTime: (params?.innerText || "").includes("Simplification time"),
      hasSpinner: !!params?.querySelector(".params-spinner"),
      kids,
      hud: document.getElementById("traceLoadingHud")?.classList.contains("visible"),
    };
  });
}

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = server.address().port;
const browser = await chromium.launch({ channel: "chrome" });
const out = {};

try {
  const fixture = await browser.newPage();
  await fixture.setViewportSize({ width: 1280, height: 800 });
  await fixture.goto(`http://127.0.0.1:${port}/usability/desktop-loading-params.html`, {
    waitUntil: "domcontentloaded",
  });
  await fixture.screenshot({
    path: join(WEB, "usability/desktop-loading-params.png"),
    fullPage: true,
  });
  await fixture.close();

  for (const size of [
    { name: "1280", width: 1280, height: 800 },
    { name: "900", width: 900, height: 700 },
    { name: "390", width: 390, height: 844 },
  ]) {
    const page = await browser.newPage();
    await page.setViewportSize({ width: size.width, height: size.height });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await waitForOption(page);
    if (size.width <= 720) {
      await page.click("#preloadedTrigger");
      await page.waitForTimeout(150);
      await page.click(".trace-picker-item");
    } else {
      await page.selectOption("#traceSelect", "1");
    }
    await page.click("#loadBtn");
    await page.waitForFunction(() => document.body.classList.contains("trace-loading"), { timeout: 4000 });
    await page.waitForTimeout(250);
    out[`loading${size.name}`] = await measureLoading(page);
    await page.screenshot({
      path: join(WEB, `usability/desktop-loading-params-${size.name}-live.png`),
      fullPage: false,
    });
    await page.close();
  }

  writeFileSync("/tmp/desktop-loading-params-measure.json", JSON.stringify(out, null, 2));
  console.log(JSON.stringify(out, null, 2));
} finally {
  await browser.close();
  server.close();
}
